import os,json,gzip,zlib,re,base64,pathlib
p=pathlib.Path('store/jobs/j000321/out/storage-authenticated-payload.bin').read_bytes()
out=pathlib.Path(os.environ['OUT'])
res={'length':len(p),'prefix_hex':p[:32].hex(),'suffix_hex':p[-32:].hex(),'parses':[]}
variants=[('raw',p)]
for name,fn in [('gzip',gzip.decompress),('zlib',zlib.decompress),('rawdeflate',lambda x:zlib.decompress(x,-15))]:
 try:
  q=fn(p); variants.append((name,q));res['parses'].append({'codec':name,'ok':True,'length':len(q),'prefix_hex':q[:16].hex()})
 except Exception as e:res['parses'].append({'codec':name,'ok':False,'error':type(e).__name__})
for vn,b in variants:
 for enc in ['utf-8','utf-16le']:
  try:
   t=b.decode(enc)
   rec={'variant':vn,'encoding':enc,'decoded':True,'chars':len(t)}
   try:
    o=json.loads(t);rec['json']=True;rec['json_type']=type(o).__name__;rec['keys']=sorted(o.keys()) if isinstance(o,dict) else None
    (out/f'{vn}-{enc}-parsed.json').write_text(json.dumps(o,ensure_ascii=False,indent=2))
   except Exception:rec['json']=False
   res['parses'].append(rec)
  except Exception:pass
# bounded printable strings and likely contact contexts. This sealed secret output may include personal data; do not print values.
strings=[]
for m in re.finditer(rb'[ -~]{4,}',p): strings.append({'offset':m.start(),'value':m.group().decode('ascii','replace')})
for m in re.finditer(rb'(?:[ -~]\x00){4,}',p): strings.append({'offset':m.start(),'value':m.group().decode('utf-16le','replace')})
strings.sort(key=lambda x:x['offset'])
(out/'all-printable-strings.json').write_text(json.dumps(strings,ensure_ascii=False,indent=2))
terms=['contact','recipient','person','name','email','mail','address','sender','client','note','label','identity','strange','maroni','nigma','falcone']
hits=[]
for s in strings:
 low=s['value'].lower()
 if any(x in low for x in terms) or re.search(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',s['value']):hits.append(s)
(out/'contact-indicator-strings.json').write_text(json.dumps(hits,ensure_ascii=False,indent=2))
res['string_count']=len(strings);res['contact_indicator_count']=len(hits)
(out/'structure-summary.json').write_text(json.dumps(res,indent=2))
print(json.dumps({'length':len(p),'variants':[x[0] for x in variants],'strings':len(strings),'contact_indicators':len(hits),'summary':'structure-summary.json'}))
